            "<tr><th>5th Level</th><td></td></tr>",
            "<tr><td>Archon, hound</td><td>LG</td></tr>",
            "<tr><td>Celestial brown bear</td><td>LG</td></tr>",
            "<tr><td>Celestial giant stag beetle</td><td>NG</td></tr>",
            "<tr><td>Celestial sea cat1</td><td>NG</td></tr>",
            "<tr><td>Celestial griffon</td><td>CG</td></tr>",
