            "<tr><td>Hill giants, fiendish</td><td>3</td><td>CE</td></tr>",
            "<tr><td>Stone giants, celestial or fiendish</td><td>2</td><td>N</td></tr>",
            "<tr><td>Frost giant, fiendish</td><td>1</td><td>CE</td></tr>",
            "<tr><td>Fire giant, fiendish</td><td>1</td><td>LE</td></tr>",
