            "<tr><td>Garl Glittergold</td><td>Spell resistance 13</td></tr>",
            "<tr><td>Gruumsh</td><td>Arrow deflection</td></tr>",
            "<tr><td>Heironeous</td><td>Electricity resistance 5</td></tr>",
            "<tr><td>Hextor</td><td>Damage reduction 2/magic</td></tr>",
            "<tr><td>Kord</td><td>Damage reduction 2/magic</td></tr>",
            "<tr><td>Kurtulmak</td><td>Shadow and silent moves</td></tr>",
            "<tr><td>Lolth</td><td>50% fortification (half of critical hits are negated)</td></tr>",
            "<tr><td>Moradin</td><td>Arrow deflection</td></tr>",
            "<tr><td>Nerull</td><td>50% fortification (half of critical hits are negated)</td></tr>",
            "<tr><td>Obad-Hai</td><td>Shadow and silent moves</td></tr>",
            "<tr><td>Olidammara</td><td>Shadow and silent moves</td></tr>",
            "<tr><td>Pelor</td><td>Fire resistance 5</td></tr>",
            "<tr><td>St. Cuthbert</td><td>Damage reduction 2/magic</td></tr>",
